package android.content;
public final class ContentValues {private final java.util.Map<String,Object> values=new java.util.HashMap<String,Object>();public void put(String k,String v){values.put(k,v);}public void put(String k,Integer v){values.put(k,v);}public void put(String k,Long v){values.put(k,v);}public void put(String k,Boolean v){values.put(k,v);}public Object get(String k){return values.get(k);}public String getAsString(String k){Object v=values.get(k);return v==null?null:v.toString();}public java.util.Set<java.util.Map.Entry<String,Object>> valueSet(){return values.entrySet();}public int size(){return values.size();}}
